package com.battlemage;

import java.awt.Color;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

/**
 * Every visual setting the overlays read, with a draft layer on top for the side panel's
 * appearance editor.
 *
 * <p>The values are stored as hidden items in {@link BattleMageConfig}, so they persist like any
 * other setting but never appear in RuneLite's configuration panel. While the editor is open,
 * {@link #set} writes into a draft that the overlays read straight away - the change is visible on
 * screen - but nothing reaches the config until {@link #apply()}. {@link #cancel()} throws the
 * draft away.
 *
 * <p>The editor can also ask the overlays to show a <b>sample</b> of something that is not
 * currently happening - a state text, the effect badges, a low or overcharged bar - so every
 * setting can be judged by eye. While a state text is sampled it can be dragged with the mouse to
 * place it.
 */
@Singleton
public class Appearance
{
	/** Which state the overlays should pretend is active, for the preview. */
	enum Sample
	{
		NONE, DEPLETED, OVERLOAD, CRITICAL
	}

	/** Defaults, in one place, for the editor's "Reset to defaults". Match {@link BattleMageConfig}. */
	static final Map<String, Object> DEFAULTS = new LinkedHashMap<>();

	/** A state-text position of -1 means "not placed by hand": the text sits centred above the PKP bar. */
	static final double ANCHORED = -1.0;

	/** Gap, in pixels, between the bottom of the state text and the top of the PKP bar. */
	static final int ANCHOR_GAP_PX = 50;

	static
	{
		DEFAULTS.put("showBar", true);
		DEFAULTS.put("barLabel", "PKP");
		DEFAULTS.put("showPkpValue", true);
		DEFAULTS.put("barWidth", 220);
		DEFAULTS.put("barHeight", 24);
		DEFAULTS.put("barBorderThickness", 2);
		DEFAULTS.put("barGlow", 0);
		DEFAULTS.put("barPulse", true);
		DEFAULTS.put("showCostTicks", true);
		DEFAULTS.put("barColorFull", new Color(0x46C8FF));
		DEFAULTS.put("barColorLow", new Color(0xFF4040));
		DEFAULTS.put("overchargeColor", new Color(0x9CFF57));
		DEFAULTS.put("showEffectTimers", true);
		DEFAULTS.put("effectIconSize", 34);
		DEFAULTS.put("effectBorderEnabled", true);
		DEFAULTS.put("desaturateScreen", true);
		DEFAULTS.put("desaturationStrength", 77);
		DEFAULTS.put("depletedTextScalePercent", 100);
		DEFAULTS.put("overloadTextScalePercent", 100);
		DEFAULTS.put("criticalTextScalePercent", 100);
		DEFAULTS.put("depletedText", "PKP DEPLETED");
		DEFAULTS.put("overloadText", "PKP OVERLOAD");
		DEFAULTS.put("criticalText", "CRITICAL OVERLOAD");
		DEFAULTS.put("depletedColor", new Color(0xFF2A2A));
		DEFAULTS.put("overloadColor", new Color(0xC04AFF));
		DEFAULTS.put("criticalColor", new Color(0xFFB300));
		// -1 = not placed by hand: sit centred, 50px above the PKP bar (see PkpStateOverlay)
		DEFAULTS.put("stateTextXPercent", ANCHORED);
		DEFAULTS.put("stateTextYPercent", ANCHORED);
		DEFAULTS.put("criticalTextXPercent", ANCHORED);
		DEFAULTS.put("criticalTextYPercent", ANCHORED);
		DEFAULTS.put("pkpPopupsEnabled", true);
		DEFAULTS.put("pkpPopupSeconds", 3);
		DEFAULTS.put("inventoryTooltips", true);
		DEFAULTS.put("castCardsEnabled", true);
		DEFAULTS.put("levelUpCards", true);
		DEFAULTS.put("meleeColor", new Color(0xF2F2F2));
		DEFAULTS.put("combatSpellColor", new Color(0x46C8FF));
		DEFAULTS.put("curseSpellColor", new Color(0xFF4FD8));
		DEFAULTS.put("illegalInventoryShade", new Color(0xFFB300));
		DEFAULTS.put("illegalExemptOutline", new Color(0x39FF14));
	}

	private final BattleMageConfig config;
	private final ConfigManager configManager;
	private final MouseManager mouseManager;
	private final Client client;

	private final Map<String, Object> draft = new ConcurrentHashMap<>();
	private volatile boolean editing;
	private volatile Sample sample = Sample.NONE;
	/** Bar fill to show instead of the real one, 0..1, or negative for the real value. */
	private volatile double sampleFill = -1;
	private volatile boolean sampleOvercharge;
	private volatile boolean sampleEffects;

	/** Where the state text was last drawn, in canvas pixels - what a drag has to land on. */
	private volatile Rectangle stateTextBounds;
	private volatile boolean dragging;
	private int dragDx;
	private int dragDy;
	private Runnable onDraftChange = () ->
	{
	};

	private final MouseAdapter dragHandler = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			Rectangle b = stateTextBounds;
			if (editing && draggableSample() && b != null && b.contains(e.getPoint()))
			{
				dragging = true;
				dragDx = e.getX() - (int) b.getCenterX();
				dragDy = e.getY() - (int) b.getCenterY();
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent e)
		{
			if (dragging)
			{
				moveStateText(e.getX() - dragDx, e.getY() - dragDy);
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (dragging)
			{
				dragging = false;
				e.consume();
			}
			return e;
		}
	};

	@Inject
	Appearance(BattleMageConfig config, ConfigManager configManager, MouseManager mouseManager, Client client)
	{
		this.config = config;
		this.configManager = configManager;
		this.mouseManager = mouseManager;
		this.client = client;
	}

	// ------------------------------------------------------------------ editing

	/** Opens a draft (or keeps the open one). Nothing changes until something is {@link #set}. */
	void begin(Runnable onDraftChange)
	{
		this.onDraftChange = onDraftChange == null ? () ->
		{
		} : onDraftChange;
		if (editing)
		{
			return;
		}
		draft.clear();
		editing = true;
		mouseManager.registerMouseListener(dragHandler);
	}

	boolean isEditing()
	{
		return editing;
	}

	/** Puts a value in the draft; the overlays show it at once. */
	void set(String key, Object value)
	{
		if (editing && value != null)
		{
			draft.put(key, value);
		}
	}

	/** Writes the draft to the config and closes the editor. */
	void apply()
	{
		for (Map.Entry<String, Object> e : draft.entrySet())
		{
			configManager.setConfiguration(BattleMageConfig.GROUP, e.getKey(), e.getValue());
		}
		end();
	}

	/** Throws the draft away and closes the editor. */
	void cancel()
	{
		end();
	}

	/** Puts every default into the draft. Still needs {@link #apply()} to stick. */
	void resetDraftToDefaults()
	{
		if (editing)
		{
			draft.putAll(DEFAULTS);
		}
	}

	private void end()
	{
		if (!editing)
		{
			return;
		}
		editing = false;
		dragging = false;
		draft.clear();
		clearSamples();
		mouseManager.unregisterMouseListener(dragHandler);
	}

	// ------------------------------------------------------------------ samples

	void showSample(Sample s)
	{
		sample = s == null ? Sample.NONE : s;
	}

	void showSampleFill(double fill, boolean overcharge)
	{
		sampleFill = fill;
		sampleOvercharge = overcharge;
	}

	void showSampleEffects(boolean on)
	{
		sampleEffects = on;
	}

	void clearSamples()
	{
		sample = Sample.NONE;
		sampleFill = -1;
		sampleOvercharge = false;
		sampleEffects = false;
	}

	/** The state the overlays should draw for the preview, or NONE for the real one. */
	Sample sample()
	{
		return editing ? sample : Sample.NONE;
	}

	/** A bar fill to preview (0..1), or negative to draw the real fill. */
	double sampleFill()
	{
		return editing ? sampleFill : -1;
	}

	boolean sampleOvercharge()
	{
		return editing && sampleOvercharge;
	}

	boolean sampleEffects()
	{
		return editing && sampleEffects;
	}

	// ---------------------------------------------------------------- dragging

	void setStateTextBounds(Rectangle bounds)
	{
		stateTextBounds = bounds;
	}

	private boolean draggableSample()
	{
		return sample != Sample.NONE;
	}

	/** The config keys that hold where the given state's text sits. Critical has its own pair. */
	static String[] positionKeys(Sample s)
	{
		return s == Sample.CRITICAL
			? new String[]{"criticalTextXPercent", "criticalTextYPercent"}
			: new String[]{"stateTextXPercent", "stateTextYPercent"};
	}

	/** The default position for the given state's text, in percent of the canvas. */
	static double[] defaultPosition(Sample s)
	{
		return new double[]{ANCHORED, ANCHORED};
	}

	private void moveStateText(int cx, int cy)
	{
		int cw = client.getCanvasWidth();
		int ch = client.getCanvasHeight();
		if (cw <= 0 || ch <= 0)
		{
			return;
		}
		double x = Math.max(0, Math.min(100, cx * 100.0 / cw));
		double y = Math.max(0, Math.min(100, cy * 100.0 / ch));
		String[] keys = positionKeys(sample);
		draft.put(keys[0], Math.round(x * 10) / 10.0);
		draft.put(keys[1], Math.round(y * 10) / 10.0);
		onDraftChange.run();
	}

	// ------------------------------------------------------------------ reading

	@SuppressWarnings("unchecked")
	private <T> T get(String key, Supplier<T> stored)
	{
		if (editing)
		{
			Object v = draft.get(key);
			if (v != null)
			{
				return (T) v;
			}
		}
		return stored.get();
	}

	boolean showBar()
	{
		return get("showBar", config::showBar);
	}

	String barLabel()
	{
		return get("barLabel", config::barLabel);
	}

	boolean showPkpValue()
	{
		return get("showPkpValue", config::showPkpValue);
	}

	int barWidth()
	{
		return get("barWidth", config::barWidth);
	}

	int barHeight()
	{
		return get("barHeight", config::barHeight);
	}

	int barBorderThickness()
	{
		return get("barBorderThickness", config::barBorderThickness);
	}

	int barGlow()
	{
		return get("barGlow", config::barGlow);
	}

	boolean barPulse()
	{
		return get("barPulse", config::barPulse);
	}

	boolean showCostTicks()
	{
		return get("showCostTicks", config::showCostTicks);
	}

	Color barColorFull()
	{
		return get("barColorFull", config::barColorFull);
	}

	Color barColorLow()
	{
		return get("barColorLow", config::barColorLow);
	}

	Color overchargeColor()
	{
		return get("overchargeColor", config::overchargeColor);
	}

	boolean showEffectTimers()
	{
		return get("showEffectTimers", config::showEffectTimers);
	}

	int effectIconSize()
	{
		return get("effectIconSize", config::effectIconSize);
	}

	boolean effectBorderEnabled()
	{
		return get("effectBorderEnabled", config::effectBorderEnabled);
	}

	boolean desaturateScreen()
	{
		return get("desaturateScreen", config::desaturateScreen);
	}

	int desaturationStrength()
	{
		return get("desaturationStrength", config::desaturationStrength);
	}

	int depletedTextScalePercent()
	{
		return get("depletedTextScalePercent", config::depletedTextScalePercent);
	}

	int overloadTextScalePercent()
	{
		return get("overloadTextScalePercent", config::overloadTextScalePercent);
	}

	int criticalTextScalePercent()
	{
		return get("criticalTextScalePercent", config::criticalTextScalePercent);
	}

	String depletedText()
	{
		return get("depletedText", config::depletedText);
	}

	String overloadText()
	{
		return get("overloadText", config::overloadText);
	}

	String criticalText()
	{
		return get("criticalText", config::criticalText);
	}

	Color depletedColor()
	{
		return get("depletedColor", config::depletedColor);
	}

	Color overloadColor()
	{
		return get("overloadColor", config::overloadColor);
	}

	Color criticalColor()
	{
		return get("criticalColor", config::criticalColor);
	}

	double stateTextXPercent()
	{
		return get("stateTextXPercent", config::stateTextXPercent);
	}

	double stateTextYPercent()
	{
		return get("stateTextYPercent", config::stateTextYPercent);
	}

	double criticalTextXPercent()
	{
		return get("criticalTextXPercent", config::criticalTextXPercent);
	}

	double criticalTextYPercent()
	{
		return get("criticalTextYPercent", config::criticalTextYPercent);
	}

	boolean pkpPopupsEnabled()
	{
		return get("pkpPopupsEnabled", config::pkpPopupsEnabled);
	}

	int pkpPopupSeconds()
	{
		return get("pkpPopupSeconds", config::pkpPopupSeconds);
	}

	boolean inventoryTooltips()
	{
		return get("inventoryTooltips", config::inventoryTooltips);
	}

	boolean castCardsEnabled()
	{
		return get("castCardsEnabled", config::castCardsEnabled);
	}

	boolean levelUpCards()
	{
		return get("levelUpCards", config::levelUpCards);
	}

	Color meleeColor()
	{
		return get("meleeColor", config::meleeColor);
	}

	Color combatSpellColor()
	{
		return get("combatSpellColor", config::combatSpellColor);
	}

	Color curseSpellColor()
	{
		return get("curseSpellColor", config::curseSpellColor);
	}

	/** Wash over the inventory and worn equipment during CRITICAL OVERLOAD. */
	Color illegalInventoryShade()
	{
		return get("illegalInventoryShade", config::illegalInventoryShade);
	}

	/** Outline around the item that stays usable during CRITICAL OVERLOAD. */
	Color illegalExemptOutline()
	{
		return get("illegalExemptOutline", config::illegalExemptOutline);
	}
}

package com.battlemage;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JColorChooser;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JTextField;
import javax.swing.JToggleButton;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The side panel's appearance menu: every visual setting, previewed on screen as it changes, and
 * only saved when <b>Apply</b> is pressed.
 *
 * <p>Touching a control also puts a matching sample on screen - the state text for the text
 * settings, the badges for the effect settings, a near-empty bar for the low colour - so each
 * setting is judged by eye rather than by number. The state text can be dragged on screen to place
 * it.
 */
class AppearanceEditor extends JPanel
{
	private static final Color ACCENT = new Color(0x46C8FF);

	private final Appearance look;
	private final Previews previews;

	/** Things the plugin can put on screen on request, for the preview. */
	interface Previews
	{
		/** A sample +/- PKP popup pair. */
		void popups();

		/** A sample cast card in the given family's colour. */
		void castCard(PsiAction family);

		/** A sample level-up card. */
		void levelUp();
	}
	private final Runnable onClose;
	private final Runnable onReload;

	/** The state the text section previews; the three buttons switch it. */
	private Appearance.Sample stateSample = Appearance.Sample.DEPLETED;
	private final JToggleButton[] stateButtons = new JToggleButton[3];
	private final JLabel position = new JLabel();

	/**
	 * @param onClose  called after Apply or Cancel, to put the normal side panel back
	 * @param onReload called to rebuild this editor from the current draft (after Reset)
	 */
	AppearanceEditor(Appearance look, Previews previews, Runnable onClose, Runnable onReload)
	{
		this.look = look;
		this.previews = previews;
		this.onClose = onClose;
		this.onReload = onReload;
		// Opening the editor a second time (after Reset) keeps the draft that is already open.
		look.begin(() -> javax.swing.SwingUtilities.invokeLater(this::refreshPosition));

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel title = new JLabel("Customize appearance");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(title);
		add(note("Changes show on screen straight away. Nothing is saved until you press Apply."));
		add(Box.createVerticalStrut(6));
		add(buttons());

		// ---------------------------------------------------------------- PKP bar
		add(section("PKP bar"));
		Runnable bar = () -> sample(Appearance.Sample.NONE, -1, false, false);
		add(check("Show PKP bar", "showBar", look.showBar(), bar));
		add(text("Bar label", "barLabel", look.barLabel(), bar));
		add(check("Show numbers (off = percentages)", "showPkpValue", look.showPkpValue(), bar));
		add(slider("Width", "barWidth", 80, 1000, look.barWidth(), v -> v + " px", bar));
		add(slider("Height", "barHeight", 10, 80, look.barHeight(), v -> v + " px", bar));
		add(slider("Border", "barBorderThickness", 1, 8, look.barBorderThickness(), v -> v + " px", bar));
		add(slider("Glow", "barGlow", 0, 12, look.barGlow(), v -> v == 0 ? "off" : v + " px", bar));
		add(check("Pulse", "barPulse", look.barPulse(), bar));
		add(check("Cost ticks", "showCostTicks", look.showCostTicks(), bar));
		add(colour("Full colour", "barColorFull", look.barColorFull(), () -> sample(Appearance.Sample.NONE, 1.0, false, false)));
		add(colour("Low colour", "barColorLow", look.barColorLow(), () -> sample(Appearance.Sample.NONE, 0.12, false, false)));
		add(colour("Overcharge colour", "overchargeColor", look.overchargeColor(), () -> sample(Appearance.Sample.NONE, 1.0, true, false)));

		// ---------------------------------------------------------------- effects
		add(section("Effect badges"));
		Runnable fx = () -> sample(Appearance.Sample.NONE, -1, false, true);
		add(check("Show effect timers", "showEffectTimers", look.showEffectTimers(), fx));
		add(slider("Badge size", "effectIconSize", 20, 96, look.effectIconSize(), v -> v + " px", fx));
		add(check("Effects on bar border", "effectBorderEnabled", look.effectBorderEnabled(), fx));

		// ---------------------------------------------------------------- state text
		add(section("State text"));
		add(stateButtons());
		position.setFont(FontManager.getRunescapeSmallFont());
		position.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		position.setAlignmentX(Component.LEFT_ALIGNMENT);
		refreshPosition();
		add(position);
		JButton centre = smallButton("Reset this text's position");
		centre.addActionListener(e ->
		{
			String[] keys = Appearance.positionKeys(stateSample);
			double[] home = Appearance.defaultPosition(stateSample);
			look.set(keys[0], home[0]);
			look.set(keys[1], home[1]);
			pickState(stateSample);
		});
		add(centre);
		add(Box.createVerticalStrut(4));
		Runnable dep = () -> pickState(Appearance.Sample.DEPLETED);
		Runnable over = () -> pickState(Appearance.Sample.OVERLOAD);
		Runnable crit = () -> pickState(Appearance.Sample.CRITICAL);
		add(text("Depleted text", "depletedText", look.depletedText(), dep));
		add(slider("Depleted text size", "depletedTextScalePercent", 50, 500, look.depletedTextScalePercent(), v -> v + "%", dep));
		add(colour("Depleted colour", "depletedColor", look.depletedColor(), dep));
		add(check("Grey wash while depleted", "desaturateScreen", look.desaturateScreen(), dep));
		add(slider("Grey wash strength", "desaturationStrength", 0, 255, look.desaturationStrength(),
			v -> Math.round(v * 100 / 255.0) + "%", dep));
		add(text("Overload text", "overloadText", look.overloadText(), over));
		add(slider("Overload text size", "overloadTextScalePercent", 50, 500, look.overloadTextScalePercent(), v -> v + "%", over));
		add(colour("Overload colour", "overloadColor", look.overloadColor(), over));
		add(text("Critical overload text", "criticalText", look.criticalText(), crit));
		add(slider("Critical overload text size", "criticalTextScalePercent", 50, 500, look.criticalTextScalePercent(), v -> v + "%", crit));
		add(colour("Critical overload colour", "criticalColor", look.criticalColor(), crit));
		add(note("Markers on the inventory and worn equipment during critical overload:"));
		add(stackedColour("Critical Overload: inventory shade", "illegalInventoryShade",
			look.illegalInventoryShade(), crit));
		add(stackedColour("Critical Overload: exempt-item outline", "illegalExemptOutline",
			look.illegalExemptOutline(), crit));
		add(note("The outline shows on the Cowbell amulet, if you are carrying or wearing it."));

		// ---------------------------------------------------------------- cards
		add(section("Cast & level-up cards"));
		Runnable combatCard = () ->
		{
			sample(Appearance.Sample.NONE, -1, false, false);
			previews.castCard(PsiAction.COMBAT);
		};
		add(check("Show cast cards", "castCardsEnabled", look.castCardsEnabled(), combatCard));
		add(colour("Melee colour", "meleeColor", look.meleeColor(), () ->
		{
			sample(Appearance.Sample.NONE, -1, false, false);
			previews.castCard(PsiAction.MELEE);
		}));
		add(colour("Combat spell colour", "combatSpellColor", look.combatSpellColor(), combatCard));
		add(colour("Curse spell colour", "curseSpellColor", look.curseSpellColor(), () ->
		{
			sample(Appearance.Sample.NONE, -1, false, false);
			previews.castCard(PsiAction.CURSE);
		}));
		add(note("Cast cards must be on for the colour samples to show."));
		add(check("Show level-up cards", "levelUpCards", look.levelUpCards(), () ->
		{
			sample(Appearance.Sample.NONE, -1, false, false);
			previews.levelUp();
		}));

		// ---------------------------------------------------------------- popups & tooltips
		add(section("Popups & tooltips"));
		Runnable pop = () ->
		{
			sample(Appearance.Sample.NONE, -1, false, false);
			previews.popups();
		};
		add(check("PKP change popups", "pkpPopupsEnabled", look.pkpPopupsEnabled(), pop));
		add(slider("Popup duration", "pkpPopupSeconds", 1, 10, look.pkpPopupSeconds(), v -> v + " s", pop));
		add(check("Item tooltips", "inventoryTooltips", look.inventoryTooltips(), bar));

		add(Box.createVerticalStrut(10));
		add(buttons());
		JButton defaults = smallButton("Reset all to defaults");
		defaults.addActionListener(e ->
		{
			look.resetDraftToDefaults();
			onReload.run();
		});
		add(Box.createVerticalStrut(6));
		add(defaults);
	}

	// ------------------------------------------------------------------ actions

	private void sample(Appearance.Sample state, double fill, boolean overcharge, boolean effects)
	{
		look.showSample(state);
		look.showSampleFill(fill, overcharge);
		look.showSampleEffects(effects);
	}

	private void pickState(Appearance.Sample s)
	{
		stateSample = s;
		for (int i = 0; i < stateButtons.length; i++)
		{
			stateButtons[i].setSelected(i == s.ordinal() - 1);
		}
		sample(s, -1, false, false);
		refreshPosition();
	}

	private void refreshPosition()
	{
		boolean critical = stateSample == Appearance.Sample.CRITICAL;
		double x = critical ? look.criticalTextXPercent() : look.stateTextXPercent();
		double y = critical ? look.criticalTextYPercent() : look.stateTextYPercent();
		String label = critical ? "Critical" : "Depleted / overload";
		String where = (x < 0 || y < 0)
			? label + " position: above the PKP bar"
			: String.format("%s position: %.0f%% across, %.0f%% down", label, x, y);
		position.setText("<html><body style='width:170px'>" + where
			+ "<br>Drag the text on screen to move it.</body></html>");
	}

	private JPanel buttons()
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 6, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		JButton apply = smallButton("Apply");
		apply.setForeground(ACCENT);
		apply.addActionListener(e ->
		{
			look.apply();
			onClose.run();
		});
		JButton cancel = smallButton("Cancel");
		cancel.addActionListener(e ->
		{
			look.cancel();
			onClose.run();
		});
		row.add(apply);
		row.add(cancel);
		return row;
	}

	private JPanel stateButtons()
	{
		JPanel row = new JPanel(new GridLayout(1, 3, 4, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		String[] names = {"Depleted", "Overload", "Critical"};
		Appearance.Sample[] states = {Appearance.Sample.DEPLETED, Appearance.Sample.OVERLOAD, Appearance.Sample.CRITICAL};
		for (int i = 0; i < 3; i++)
		{
			final Appearance.Sample s = states[i];
			JToggleButton b = new JToggleButton(names[i]);
			b.setFont(FontManager.getRunescapeSmallFont());
			b.setFocusPainted(false);
			b.setMargin(new java.awt.Insets(2, 1, 2, 1));
			b.addActionListener(e -> pickState(s));
			stateButtons[i] = b;
			row.add(b);
		}
		stateButtons[0].setSelected(true);
		return row;
	}

	// ---------------------------------------------------------------- controls

	private interface Format
	{
		String of(int v);
	}

	private JPanel slider(String label, String key, int min, int max, int value, Format format, Runnable onTouch)
	{
		JPanel p = row();
		JLabel name = label(label);
		JLabel shown = label(format.of(value));
		shown.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(name, BorderLayout.WEST);
		top.add(shown, BorderLayout.EAST);
		p.add(top, BorderLayout.NORTH);

		JSlider s = new JSlider(min, max, Math.max(min, Math.min(max, value)));
		s.setOpaque(false);
		s.addChangeListener(e ->
		{
			shown.setText(format.of(s.getValue()));
			look.set(key, s.getValue());
			onTouch.run();
		});
		p.add(s, BorderLayout.CENTER);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		return p;
	}

	private JPanel check(String label, String key, boolean value, Runnable onTouch)
	{
		JPanel p = row();
		JCheckBox c = new JCheckBox(label, value);
		c.setFont(FontManager.getRunescapeSmallFont());
		c.setForeground(Color.WHITE);
		c.setOpaque(false);
		c.setFocusPainted(false);
		c.addActionListener(e ->
		{
			look.set(key, c.isSelected());
			onTouch.run();
		});
		p.add(c, BorderLayout.CENTER);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		return p;
	}

	private JPanel text(String label, String key, String value, Runnable onTouch)
	{
		JPanel p = row();
		p.add(label(label), BorderLayout.NORTH);
		JTextField f = new JTextField(value == null ? "" : value);
		f.getDocument().addDocumentListener(new DocumentListener()
		{
			private void changed()
			{
				look.set(key, f.getText());
				onTouch.run();
			}

			@Override
			public void insertUpdate(DocumentEvent e)
			{
				changed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				changed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				changed();
			}
		});
		f.addFocusListener(new java.awt.event.FocusAdapter()
		{
			@Override
			public void focusGained(java.awt.event.FocusEvent e)
			{
				onTouch.run();
			}
		});
		p.add(f, BorderLayout.CENTER);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
		return p;
	}

	/** A colour whose name is too long for one row: the name on top, the swatch on its own row. */
	private JPanel stackedColour(String label, String key, Color value, Runnable onTouch)
	{
		JPanel p = row();
		p.add(label(label), BorderLayout.NORTH);
		JButton swatch = swatch(label, key, value, onTouch);
		swatch.setPreferredSize(new Dimension(40, 20));
		p.add(swatch, BorderLayout.CENTER);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		return p;
	}

	private JButton swatch(String label, String key, Color value, Runnable onTouch)
	{
		JButton swatch = new JButton();
		swatch.setPreferredSize(new Dimension(44, 20));
		swatch.setBackground(value);
		swatch.setOpaque(true);
		swatch.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		swatch.setFocusPainted(false);
		swatch.addActionListener(e ->
		{
			onTouch.run();
			Color picked = JColorChooser.showDialog(this, label, swatch.getBackground());
			if (picked != null)
			{
				swatch.setBackground(picked);
				look.set(key, picked);
				onTouch.run();
			}
		});
		return swatch;
	}

	private JPanel colour(String label, String key, Color value, Runnable onTouch)
	{
		JPanel p = row();
		p.add(label(label), BorderLayout.CENTER);
		p.add(swatch(label, key, value, onTouch), BorderLayout.EAST);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		return p;
	}

	// ------------------------------------------------------------------ pieces

	private static JPanel row()
	{
		JPanel p = new JPanel(new BorderLayout(6, 2));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		return p;
	}

	private static JLabel label(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.WHITE);
		return l;
	}

	private static JLabel note(String text)
	{
		JLabel l = new JLabel("<html><body style='width:170px'>" + text + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel section(String title)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createEmptyBorder(12, 0, 4, 0),
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR)));
		JLabel l = new JLabel(title.toUpperCase());
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ACCENT);
		p.add(l, BorderLayout.WEST);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		return p;
	}

	private static JButton smallButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusPainted(false);
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		b.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		return b;
	}
}

