	{
		return (int) Math.round(pkp);
	}

	int minSpellCost()
	{
		return Math.min(rules.combatSpellCost(), rules.curseSpellCost());
	}

	boolean isDepleted()
	{
		return depletedLatch && !depletionImmune();
	}

	boolean isOverloaded()
