package com.battlemage;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * The plugin's own sound effects, played from a bundled WAV through RuneLite's {@link AudioPlayer}.
 *
 * <p>The oath sting is not one of the game's own sounds, so it ships as a resource. The file is 16-bit
 * PCM mono at 44.1 kHz, which every JVM can decode with no extra library.
 *
 * <p><b>Nothing here is allowed to break the plugin.</b> Sound is decoration: a machine with no audio
 * device, a missing resource or a busy output line is logged at debug level and the plugin carries on
 * in silence.
 */
@Slf4j
@Singleton
class Sfx
{
	/** The oath sting: played once, when the PKP bar first appears after a faction is chosen. */
	static final String OATH_REVEAL = "/sfx/oath-reveal.wav";

	/**
	 * The TITHES choir (in B-flat, to lead into the click sound), as short overlapping slices of one
	 * continuous pad. Played back to back every {@link #TITHES_GRAIN_MS} while the mouse is on the
	 * button they join into one seamless sound; stop scheduling them and it fades within one slice.
	 * The SWELL slices rise in volume first; the LOOP slices (the same pad with a high shimmer added)
	 * then hold for as long as the mouse stays.
	 */
	static final String[] TITHES_SWELL = {
		"/sfx/tithes-swell-1.wav", "/sfx/tithes-swell-2.wav", "/sfx/tithes-swell-3.wav", "/sfx/tithes-swell-4.wav",
	};
	static final String[] TITHES_LOOP = {
		"/sfx/tithes-loop-1.wav", "/sfx/tithes-loop-2.wav", "/sfx/tithes-loop-3.wav", "/sfx/tithes-loop-4.wav",
	};
	/** Played when TITHES is clicked; the choir stops and hands over to it. */
	static final String TITHES_CLICK = "/sfx/tithes-click.wav";
	/** Spacing between slices: half a slice's length, so each moment is covered by two of them. */
	static final long TITHES_GRAIN_MS = 320L;

	private final AudioPlayer audioPlayer;

	@Inject
	Sfx(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	/** Play a bundled effect at an exact gain in decibels (0 = as recorded, negative = quieter). */
	void playGain(String path, float gainDb)
	{
		try
		{
			audioPlayer.play(Sfx.class, path, gainDb);
		}
		catch (Exception e)
		{
			log.debug("[BATTLE-MAGE] could not play {}", path, e);
		}
	}

	/**
	 * Play a bundled effect.
	 *
	 * @param path   resource path of the WAV
	 * @param volume 0-100, where 0 means do not play at all and 100 is the file's own level
	 */
	void play(String path, int volume)
	{
		if (volume <= 0)
		{
			return;
		}
		// Gain is in decibels, so the 0-100 volume maps logarithmically: 100 = 0 dB (as recorded).
		int v = Math.max(1, Math.min(100, volume));
		float gainDb = (float) (20.0 * Math.log10(v / 100.0));
		try
		{
			audioPlayer.play(Sfx.class, path, gainDb);
		}
		catch (Exception e)
		{
			log.debug("[BATTLE-MAGE] could not play {}", path, e);
		}
	}
}

package com.battlemage;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Spellbook restriction visuals.
 * <ul>
 *   <li>ILLEGAL or DEPLETED state: the whole spellbook gets a state-coloured shade (orange for illegal,
 *       the depletion-alert colour for depleted) and EVERY spell in the book is X'd in that colour.</li>
 *   <li>Normal / overload state: only individually off-limit spells get the classic blue X.</li>
 * </ul>
 */
class SpellBlockOverlay extends Overlay
{
	private static final int SPELLBOOK_GROUP = 218;

	private final Client client;
	private final BattleMagePlugin plugin;
	private final BattleMageConfig config;

	@Inject
	SpellBlockOverlay(Client client, BattleMagePlugin plugin, BattleMageConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		Widget[] roots = client.getWidgetRoots();
		if (roots == null)
		{
			return null;
		}

		Color state = plugin.spellbookStateColor();
		if (state != null)
		{
			// ILLEGAL / DEPLETED: shade the whole book and X every spell in the state colour
			Rectangle[] union = new Rectangle[1];
			List<Rectangle> spells = new ArrayList<>();
			for (Widget root : roots)
			{
				scanSpellbook(root, 0, union, spells);
			}
			if (union[0] != null)
			{
				double blink = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 320.0);
				int a = (int) Math.round(60 + 40 * blink);
				g.setColor(new Color(state.getRed(), state.getGreen(), state.getBlue(), a));
				g.fillRect(union[0].x, union[0].y, union[0].width, union[0].height);
			}
			for (Rectangle b : spells)
			{
				drawX(g, b, state);
			}
		}
		else
		{
			// normal / overload: blue X on individually off-limit spells only
			for (Widget root : roots)
			{
				drawBlueBlocked(g, root, 0);
			}
		}
		return null;
	}

	// ---------------------------------------------------------------- ILLEGAL / DEPLETED

	/** Accumulate the spellbook panel bounds (union) and every spell-icon's bounds. */
	private void scanSpellbook(Widget w, int depth, Rectangle[] union, List<Rectangle> spells)
	{
		if (w == null || depth > 8 || w.isHidden())
		{
			return;
		}
		if ((w.getId() >>> 16) == SPELLBOOK_GROUP)
		{
			Rectangle b = w.getBounds();
			if (b != null && b.width > 0 && b.height > 0)
			{
				union[0] = union[0] == null ? new Rectangle(b) : union[0].union(b);
				if (isSpellIcon(w, b))
				{
					spells.add(b);
				}
			}
		}
		scanChildren(w.getStaticChildren(), depth, union, spells);
		scanChildren(w.getDynamicChildren(), depth, union, spells);
		scanChildren(w.getNestedChildren(), depth, union, spells);
	}

	private void scanChildren(Widget[] children, int depth, Rectangle[] union, List<Rectangle> spells)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			scanSpellbook(c, depth + 1, union, spells);
		}
	}

	/** A spell icon: a sprite-backed, icon-sized widget that is castable or carries a spell name. */
	private static boolean isSpellIcon(Widget w, Rectangle b)
	{
		if (w.getSpriteId() <= 0)
		{
			return false;
		}
		int min = Math.min(b.width, b.height);
		int max = Math.max(b.width, b.height);
		if (min < 14 || max > 40)
		{
			return false;
		}
		if (isCastable(w))
		{
			return true;
		}
		String n = w.getName();
		return n != null && !n.replaceAll("<[^>]*>", "").trim().isEmpty();
	}

	// ---------------------------------------------------------------- normal / overload

	private void drawBlueBlocked(Graphics2D g, Widget w, int depth)
	{
		if (w == null || depth > 8)
		{
			return;
		}
		if (!w.isHidden())
		{
			Color xColor = plugin.spellBlockColor(w.getName(), isCastable(w));
			if (xColor != null)
			{
				Rectangle b = w.getBounds();
				if (b != null && b.width > 0 && b.height > 0)
				{
					drawX(g, b, xColor);
				}
			}
		}
		walk(g, w.getStaticChildren(), depth);
		walk(g, w.getDynamicChildren(), depth);
		walk(g, w.getNestedChildren(), depth);
	}

	private void walk(Graphics2D g, Widget[] children, int depth)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			drawBlueBlocked(g, c, depth + 1);
		}
	}

	// ---------------------------------------------------------------- shared

	private static void drawX(Graphics2D g, Rectangle b, Color color)
	{
		int inset = Math.max(4, (int) Math.round(Math.min(b.width, b.height) * 0.30));
		int x1 = b.x + inset;
		int y1 = b.y + inset;
		int x2 = b.x + b.width - inset;
		int y2 = b.y + b.height - inset;
		g.setStroke(new BasicStroke(2.5f));
		g.setColor(new Color(0, 0, 0, 200));
		g.drawLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
		g.drawLine(x2 + 1, y1 + 1, x1 + 1, y2 + 1);
		g.setColor(color);
		g.drawLine(x1, y1, x2, y2);
		g.drawLine(x2, y1, x1, y2);
	}

	/** A castable spell icon: any spell (combat, teleport, utility) exposes a "Cast" action. */
	private static boolean isCastable(Widget w)
	{
		String[] actions = w.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (a != null && a.equalsIgnoreCase("Cast"))
			{
				return true;
			}
		}
		return false;
	}
}

package com.battlemage;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Development launcher: starts a normal RuneLite client with Battle-Mage Mode already loaded.
 *
 * <p>In IntelliJ, prefer the Gradle task <b>run</b> over running this class directly: the task passes
 * {@code -ea} and {@code --developer-mode} for you. {@link ExternalPluginManager#loadBuiltin} throws
 * "Assertions are not enabled, add '-ea' to your VM options" if it is launched without them, so the
 * failure is loud rather than mysterious - but it is still a failure.
 *
 * <p>This class lives in the test source set and is not part of the side-loaded jar.
 */
public class BattleMageLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BattleMagePlugin.class);
		RuneLite.main(args);
	}
}
